"""FlyDSL Muse Spark MoE experts: the pre-expert RMSNorm and one unweighted MXFP4
expert output per route, for expert parallelism with an expert mask.

The gather normalizes each pooled row as it loads it (RMSNorm in FP32, rounded
to BF16 as vLLM's fused_rmsnorm_expand writes it), then quantizes it to MXFP4
directly into the expert-sorted tile layout. Route r pairs its expert with the
mask's last, always-masked slot, as vLLM hands aiter one route per row. Only
routes the mask maps to this rank's experts count. Both projections use
block-scaled FP4 MFMA with FP32 accumulation; the intermediate is rounded to
BF16, then to MXFP4.
"""

import functools

import numpy as np
import torch
import flydsl.compiler as flyc
import flydsl.expr as fx
from flydsl.expr import rocdl, gpu
from flydsl.expr.typing import T, ReductionOp
from flydsl.extension.coop.warp import warp_reduce, warp_inclusive_scan
from flydsl._mlir.dialects import llvm


def _sweep(name, default):
    value = int(default)
    return value


def _sweep_bool(name, default):
    value = _sweep(name, int(default))
    if value not in (0, 1):
        raise ValueError(f'{name} must be 0 or 1')
    return value == 1


_DPP_SCAN = _sweep_bool('DPP_SCAN', True)
_DPP_INPUT = _sweep_bool('DPP_INPUT', True)


def _ptr(addr, dtype, alignment=4):
    return fx.inttoptr(fx.PointerType.get(dtype.ir_type, fx.AddressSpace.Global, alignment), fx.Int64(addr))


def _load(addr, offset, dtype=fx.Int32):
    if dtype == fx.Uint8:
        rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Uint8, 1)))
        return fx.Uint8(rocdl.raw_ptr_buffer_load(T.i8, rsrc, fx.Int32(offset), fx.Int32(0), 0))
    return fx.ptr_load(fx.add_offset(_ptr(addr, dtype, dtype.width // 8), offset))


def _store(addr, offset, value, dtype=fx.Int32):
    fx.ptr_store(dtype(value), fx.add_offset(_ptr(addr, dtype, dtype.width // 8), offset))


def _load4(addr, offset, CACHE=0):
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Int32, 16)))
    return fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x4, rsrc, fx.Int32(offset) * 4, fx.Int32(0), CACHE))


def _load4_lds(addr, offset, destination):
    rsrc = rocdl.get_buffer_rsrc(rocdl.make_buffer_ptr(_ptr(addr, fx.Int32, 16)))
    address = fx.Int32(fx.ptrtoint(destination))
    uniform = fx.Int32(rocdl.readfirstlane(T.i32, address))
    pointer = fx.inttoptr(fx.PointerType.get(fx.Int32.ir_type, fx.AddressSpace.Shared, 16), uniform)
    rocdl.raw_ptr_buffer_load_lds(rsrc, fx.to_llvm_ptr(pointer), fx.Int32(16),
                               fx.Int32(offset) * 4, fx.Int32(0), fx.Int32(0), 0)


def _pair_id(Ids, r, G):
    # Route pair r: even r is row r // 2's expert, odd r the mask's last slot.
    real = _load(Ids, r // 2)
    return (r % 2 == 0).select(real, fx.Int32(G - 1))


def _float_bits(value):
    return fx.Int32(value).bitcast(fx.Float32)


def _round_bf16(v):
    # Round to nearest even, as a BF16 store of the FP32 value rounds it.
    bits = v.bitcast(fx.Int32)
    bits = (bits + 0x7FFF + ((bits >> 16) & 1)) & fx.Int32(-65536)
    return bits.bitcast(fx.Float32)


def _norm_gains(Wn, tid, HALVES, GAIN):
    # This thread's eight columns per half of (weight + gain_center), in FP32.
    gains = []
    for h in range(HALVES):
        raw = _load4(Wn, (h * 256 + tid) * 4).bitcast(fx.BFloat16)
        gains.append([fx.Float32(raw[j]) + _float_bits(GAIN) for j in range(8)])
    return gains


def _normalize_rows(loaded, gains, red, tid, D, EPS):
    """Each row's RMSNorm over the workgroup's 256 threads, as BF16-exact FP32 values."""
    wave = tid // 64
    values = [[[fx.Float32(raw.bitcast(fx.BFloat16)[j]) for j in range(8)] for raw in row] for row in loaded]
    for u, row in enumerate(values):
        s = fx.Float32(0.0)
        for vals in row:
            for v in vals:
                s = s + v * v
        # every lane holds the wave's sum and stores the same word
        s = warp_reduce(s, ReductionOp.ADD, width=64)
        fx.ptr_store(s, fx.add_offset(red, u * 4 + wave))
    gpu.barrier()
    normalized = []
    for u, row in enumerate(values):
        total = fx.Float32(fx.ptr_load(fx.add_offset(red, u * 4)))
        for w in range(1, 4):
            total = total + fx.Float32(fx.ptr_load(fx.add_offset(red, u * 4 + w)))
        rstd = fx.rsqrt(total * (1.0 / D) + _float_bits(EPS))
        normalized.append([[_round_bf16(v * rstd * g) for v, g in zip(vals, gains[h])] for h, vals in enumerate(row)])
    # the next rows reuse red
    gpu.barrier()
    return normalized


def _max(a, b):
    return (a > b).select(a, b)


def _input_max(a, b):
    if fx.const_expr(_DPP_INPUT):
        result = fx.Float32(fx.maxnumf(a, b))
    else:
        result = _max(a, b)
    return result


def _amax_reduce(a, steps, INPUT=False):
    # Nonnegative finite float bit patterns have the same unsigned ordering.
    # The gfx950 subgroup collective folds DPP moves into native max ops.
    if fx.const_expr(INPUT and _DPP_INPUT):
        a = warp_reduce(a.bitcast(fx.Uint32), ReductionOp.MAX,
                        width=1 << steps).bitcast(fx.Float32)
    else:
        for step in range(steps):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
    return a


def _epilogue_reduce(a, DPP):
    if fx.const_expr(DPP):
        # Finite nonnegative magnitudes are ordered by their unsigned bits.
        # DPP combines the cross-lane move and max in each reduction step.
        a = warp_reduce(a.bitcast(fx.Uint32), ReductionOp.MAX,
                        width=16).bitcast(fx.Float32)
    else:
        for step in range(4):
            a = _max(a, fx.Float32(gpu.shuffle_xor(a, 1 << step, 64)))
    return a


def _prefix64(value, lane):
    if fx.const_expr(_DPP_SCAN):
        value = warp_inclusive_scan(value, ReductionOp.ADD, width=64)
    else:
        for step in range(6):
            left = fx.Int32(gpu.shuffle_up(value, 1 << step, 64))
            value = value + (lane >= (1 << step)).select(left, fx.Int32(0))
    return value


def _scale_offset(e, n, kg, N, K, ADDR_BITS):
    # [E,N/32,K/256,4,16,2,2], inverse of the stored scale permutation.
    # Power-of-two coordinates map directly to the packed address bits.
    if fx.const_expr(ADDR_BITS):
        offset = (e * N * (K // 32) + (n >> 5) * (K // 256) * 256
                  + (kg >> 3) * 256 + (kg & 3) * 64
                  + (n & 15) * 4 + ((kg >> 2) & 1) * 2 + ((n >> 4) & 1))
    else:
        offset = (e * N * (K // 32) + (n // 32) * (K // 256) * 256
                  + (kg // 8) * 256 + (kg % 4) * 64
                  + (n % 16) * 4 + (kg % 8 // 4) * 2 + (n % 32 // 16))
    return offset


def _weight_offset(e, n, kg, N, K, ADDR_BITS):
    # 32 FP4 values (16 bytes) of one logical weight row per lane.
    # The two interleaved K halves advance by a single 64-dword stride.
    if fx.const_expr(ADDR_BITS):
        offset = (e * N * (K // 8) + (n >> 4) * (K // 8) * 16
                  + kg * 64 + (n & 15) * 4)
    else:
        offset = (e * N * (K // 8) + (n // 16) * (K // 8) * 16
                  + (kg // 2) * 128 + (kg % 2) * 64 + (n % 16) * 4)
    return offset


def _mfma(a, b, c, sa, sb):
    return fx.Vector(rocdl.mfma_scale_f32_16x16x128_f8f6f4(
        T.f32x4, [a, b, c, 4, 4, 0, sa, 0, sb]))


def _mfma2(a, b, c, sa, sb, WIDE):
    if fx.const_expr(WIDE):
        return fx.Vector(rocdl.mfma_scale_f32_32x32x64_f8f6f4(
            fx.Vector.make_type(16, fx.Float32), [a, b, c, 4, 4, 0, sa, 0, sb]))
    else:
        return _mfma(a, b, c, sa, sb)


def _silu_bf16(g, u):
    exp_neg = fx.Float32(rocdl.exp2(T.f32, (-g * fx.Float32(1.4426950408889634)).ir_value()))
    inv = fx.Float32(rocdl.rcp(T.f32, (fx.Float32(1.0) + exp_neg).ir_value()))
    return fx.Float32(fx.BFloat16((g * inv) * u))


def _chiplet_order(pid, bound):
    chiplet = pid % 8
    quotient, remainder = bound // 8, bound % 8
    return chiplet * quotient + (chiplet < remainder).select(chiplet, remainder) + pid // 8


def _routed_row(Routes, offset, tile, DIRECT):
    rid = tile
    if fx.const_expr(not DIRECT):
        rid = _load(Routes, offset)
    return rid


def _w1_operands(W, WS, e, nbase, wave, lane, kg, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED):
    result = []
    for ni in range(BN // (WAVES * 16)):
        n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
        result.extend([_load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE),
                       _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE),
                       _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED),
                       _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)])
    return result


def _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED):
    if fx.const_expr(PACKED):
        # Each word contains two 16-column halves and two adjacent K slices.
        # Aligned words can be reused by the unrolled column and K loops.
        offset = (e * D * (I // 128) + (n >> 5) * (I // 256) * 64
                  + (kg >> 3) * 64 + (kg & 3) * 16 + (n & 15))
        word = _load(WS, offset)
        shift = ((((kg >> 2) & 1) * 2 + ((n >> 4) & 1)) * 8)
        scale = (word >> shift) & 255
    else:
        scale = fx.Int32(_load(WS, _scale_offset(e, n, kg, D, I, ADDR_BITS), fx.Uint8))
    return scale


def _scale_word(WS, e, n, kg, D, I):
    # Packed scale word of _w2_scale, loaded on its own.
    return _load(WS, e * D * (I // 128) + (n >> 5) * (I // 256) * 64 + (kg >> 3) * 64 + (kg & 3) * 16 + (n & 15))


def _scale_byte(word, n, kg):
    return (word >> ((((kg >> 2) & 1) * 2 + ((n >> 4) & 1)) * 8)) & 255


def _w2_operands(W, WS, e, nbase, wave, lane, kg, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED):
    result = []
    for ni in range(BN // (FRAG * 4)):
        n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
        result.extend([_load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE),
                       _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED)])
    return result


def _quantize_eight(X, t):
    return _quantize_loaded(_load4(X, t * 4))


def _quantize_loaded(raw):
    packed_input = raw.bitcast(fx.BFloat16)
    return _quantize_values([fx.Float32(packed_input[j]) for j in range(8)])


def _quantize_values(values):
    # Four adjacent lanes own one complete 32-value MXFP4 scale group.
    a = fx.absf(values[0])
    for j in range(1, 8):
        a = _input_max(a, fx.absf(values[j]))
    a = _amax_reduce(a, 2, True)
    a = _input_max(a, fx.Float32(1.0e-10))
    bits = a.bitcast(fx.Int32)
    exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
    scale = (exponent << 23).bitcast(fx.Float32)
    packed = fx.Int32(0)
    for j in range(4):
        packed = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, packed, values[j * 2], values[j * 2 + 1], scale, j))
    return packed, exponent



def _map_expert_tile(Counts, tile, lane, E, BM):
    # All waves derive the same tile mapping from the completed expert counts.
    index = (lane < E).select(lane, fx.Int32(0))
    count = _load(Counts, index)
    tiles = (lane < E).select((count + BM - 1) // BM, fx.Int32(0))
    prefix = tiles
    prefix = _prefix64(prefix, lane)
    total = fx.Int32(gpu.shuffle_idx(prefix, 63, 64))
    mask = fx.Uint64(rocdl.ballot(T.i64, prefix > tile))
    expert = fx.Int32(64) - fx.Int32(fx.ctpop(mask))
    expert = (tile < total).select(expert, fx.Int32(0))
    end = fx.Int32(gpu.shuffle_idx(prefix, expert, 64))
    length = fx.Int32(gpu.shuffle_idx(tiles, expert, 64))
    return total, expert, (tile - end + length) * BM



def _map_expert_pairs(Counts, slot, lane, E, BM, TALL, PMIN=2):
    # Also returns the slot's first row tile and its row span. With TALL, the
    # first slots cover two consecutive row tiles each of the experts with at
    # least PMIN tiles, so these longer workgroups are dispatched first; the
    # remaining slots are single tiles.
    if fx.const_expr(not TALL):
        total, expert, first_row = _map_expert_tile(Counts, slot, lane, E, BM)
        return total, expert, first_row, slot, fx.Int32(BM)
    index = (lane < E).select(lane, fx.Int32(0))
    count = _load(Counts, index)
    tiles = (lane < E).select((count + BM - 1) // BM, fx.Int32(0))
    pairs = (tiles < PMIN).select(fx.Int32(0), tiles >> 1)
    singles = tiles - pairs * 2
    pair_prefix = _prefix64(pairs, lane)
    single_prefix = _prefix64(singles, lane)
    tile_prefix = pair_prefix * 2 + single_prefix
    paired = fx.Int32(gpu.shuffle_idx(pair_prefix, 63, 64))
    total = paired + fx.Int32(gpu.shuffle_idx(single_prefix, 63, 64))
    in_pairs = slot < paired
    target = in_pairs.select(slot, slot - paired)
    prefix = in_pairs.select(pair_prefix, single_prefix)
    mask = fx.Uint64(rocdl.ballot(T.i64, prefix > target))
    expert = fx.Int32(64) - fx.Int32(fx.ctpop(mask))
    expert = (slot < total).select(expert, fx.Int32(0))
    end = fx.Int32(gpu.shuffle_idx(prefix, expert, 64))
    length = fx.Int32(gpu.shuffle_idx(in_pairs.select(pairs, singles), expert, 64))
    own = fx.Int32(gpu.shuffle_idx(tiles, expert, 64))
    tile_start = fx.Int32(gpu.shuffle_idx(tile_prefix, expert, 64)) - own
    paired_own = own - fx.Int32(gpu.shuffle_idx(singles, expert, 64))
    local = in_pairs.select((target - end + length) * 2, paired_own + target - end + length)
    span = in_pairs.select(fx.Int32(2 * BM), fx.Int32(BM))
    return total, expert, local * BM, tile_start + local, span


@flyc.kernel
def _gemm1(A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
           Routes: fx.Int64, Counts: fx.Int64, TileE: fx.Int64, TileR: fx.Int64,
           Total: fx.Int64, H: fx.Int64, Q: fx.Int64, QS: fx.Int64,
           R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int],
           TOPK: fx.Constexpr[int], BM: fx.Constexpr[int], BN: fx.Constexpr[int],
           SORTED: fx.Constexpr[bool], PARTS: fx.Constexpr[int], LDS: fx.Constexpr[bool], PF: fx.Constexpr[bool], FUSED_Q: fx.Constexpr[bool], QMAX: fx.Constexpr[bool], DIRECT: fx.Constexpr[bool], KSTEP: fx.Constexpr[int], WAVES: fx.Constexpr[int], ADDR_BITS: fx.Constexpr[bool], GROUP_M: fx.Constexpr[int], PINGPONG: fx.Constexpr[bool], DMA: fx.Constexpr[bool], ROW_PAD: fx.Constexpr[int], CACHE: fx.Constexpr[int], PACKED: fx.Constexpr[bool], ROW_MAJOR: fx.Constexpr[bool], QSHUFFLE: fx.Constexpr[bool], EPILOGUE_DPP: fx.Constexpr[bool], APF: fx.Constexpr[bool],
           Local: fx.Int64, Out: fx.Int64, M: fx.Constexpr[int], ZERO: fx.Constexpr[bool]):
    THREADS = WAVES * 64
    NR = BN // (WAVES * 16)
    pid = fx.Int32(fx.block_idx.x)
    bound = fx.Int32(R * (I // BN))
    if fx.const_expr(not DIRECT):
        bound = _load(Total, 0) * (I // BN)
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    split = fx.Int32(fx.block_idx.y)
    smem = fx.SharedAllocator()
    if fx.const_expr(LDS):
        shared = fx.recast_iter(fx.Int32, smem.allocate(BM * 4 * 20 * KSTEP * (2 if PINGPONG else 1), alignment=16).peek().ptr)
    if fx.const_expr(FUSED_Q and BN // WAVES == 16):
        qshared = fx.recast_iter(fx.Float32, smem.allocate(BM * (WAVES if QMAX else BN + 4) * 4, alignment=16).peek().ptr)
    if fx.const_expr(QSHUFFLE):
        qbytes = fx.recast_iter(fx.Uint8, smem.allocate(BM * BN // 2, alignment=16).peek().ptr)
        qwords = fx.recast_iter(fx.Int32, qbytes)
    if pid < bound:
        if fx.const_expr(ZERO):
            # Output rows without exactly one local route are summed atomically
            # later; clearing them here overlaps the stores with the GEMM.
            per = (M + bound - 1) // bound
            per = (per <= 64).select(per, fx.Int32(0))
            token = pid * per + lane
            clear = (lane < per) & (token < M)
            clear = clear & (_local_routes(Local, clear.select(token, fx.Int32(0)), TOPK) != 1)
            flags = fx.Uint64(rocdl.ballot(T.i64, clear))
            zero = fx.Vector.filled(4, 0, fx.Int32)
            for t in range(per):
                if (flags >> fx.Uint64(t)) & fx.Uint64(1) != fx.Uint64(0):
                    for c in fx.range_constexpr(D // 8 // THREADS):
                        fx.ptr_store(zero, fx.add_offset(_ptr(Out, fx.Int32, 16), ((pid * per + fx.Int32(t)) * (D // 8) + c * THREADS + tid) * 4))
        ordered = _chiplet_order(pid, bound)
        tile = ordered // (I // BN)
        nbase = ordered % (I // BN) * BN
        e = _load(TileE, tile)
        rb, count = fx.Int32(0), fx.Int32(1)
        if fx.const_expr(not DIRECT):
            rb = _load(TileR, tile)
            count = _load(Counts, e)
        if fx.const_expr(GROUP_M > 1):
            # Transpose complete row-tile groups within one expert. An
            # incomplete final group keeps its original traversal.
            member = (rb // BM) % GROUP_M
            first_row = rb - member * BM
            if first_row + (GROUP_M - 1) * BM < count:
                local = member * (I // BN) + ordered % (I // BN)
                tile = tile - member + local % GROUP_M
                rb = first_row + (local % GROUP_M) * BM
                nbase = (local // GROUP_M) * BN
        rows = []
        for mi in fx.range_constexpr(BM // 16):
            row = rb + mi * 16 + lane % 16
            rid = fx.Int32(0)
            if row < count:
                rid = _routed_row(Routes, e * R + row, tile, DIRECT)
            rows.append(rid // TOPK)
        zeros = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(BM // 16 * NR * 2)]
        if fx.const_expr(PF):
            zeros = zeros + _w1_operands(W, WS, e, nbase, wave, lane, split * (D // 32 // PARTS) + lane // 16, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED)
        WEND = len(zeros)
        if fx.const_expr(APF):
            # The next activation step is loaded while this one computes.
            zeros = zeros + _a_chunk(A, AS, tile, fx.Int32(0), tid, BM, KSTEP, 1, D)
        for kk, state in range(0, D // 128 // PARTS, KSTEP, init=zeros):
            lds_base = fx.Int32(0)
            if fx.const_expr(APF):
                gpu.barrier()
                staged = state[WEND:]
                for cp in fx.range_constexpr(len(staged) // 2):
                    ix = tid + cp * 256
                    fx.ptr_store(fx.Vector(staged[cp * 2]), fx.add_offset(shared, ix * 4))
                    fx.ptr_store(fx.Int32(staged[cp * 2 + 1]), fx.add_offset(shared, BM * 16 * KSTEP + ix))
                following = (fx.Int32(kk) + KSTEP < D // 128).select(fx.Int32(kk) + KSTEP, fx.Int32(kk))
                staged = _a_chunk(A, AS, tile, following, tid, BM, KSTEP, 1, D)
                gpu.barrier()
            elif fx.const_expr(SORTED and LDS):
                if fx.const_expr(PINGPONG):
                    lds_base = ((fx.Int32(kk) // KSTEP) & 1) * (BM * 20 * KSTEP)
                else:
                    gpu.barrier()
                for cp in fx.range_constexpr((BM * 4 * KSTEP + THREADS - 1) // THREADS):
                    ix = tid + cp * THREADS
                    if ix < BM * 4 * KSTEP:
                        gi = (tile * (D // 32) + fx.Int32(kk) * 4) * BM + ix
                        if fx.const_expr(ROW_PAD != 0):
                            gi = (tile * (D // 32) + fx.Int32(kk) * 4 + ix // BM) * (BM + ROW_PAD) + ix % BM
                        if fx.const_expr(DMA):
                            _load4_lds(A, gi * 4, fx.add_offset(shared, lds_base + (wave * 64 + cp * THREADS) * 4))
                            ss = fx.Int32(_load(AS, gi, fx.Uint8))
                            fx.ptr_store(ss, fx.add_offset(shared, lds_base + BM * 16 * KSTEP + ix))
                        else:
                            vv = _load4(A, gi * 4)
                            ss = fx.Int32(_load(AS, gi, fx.Uint8))
                            fx.ptr_store(vv, fx.add_offset(shared, lds_base + ix * 4))
                            fx.ptr_store(ss, fx.add_offset(shared, lds_base + BM * 16 * KSTEP + ix))
                if fx.const_expr(DMA):
                    rocdl.s_waitcnt(vmcnt=0)
                gpu.barrier()
            accum = [fx.Vector(x) for x in state[:BM // 16 * NR * 2]]
            if fx.const_expr(PF):
                current_w = state[BM // 16 * NR * 2:WEND]
            for ki in fx.range_constexpr(KSTEP):
                kg = ((fx.Int32(kk) + ki) + split * (D // 128 // PARTS)) * 4 + lane // 16
                if fx.const_expr(ROW_MAJOR):
                    operands = _w1_operands(W, WS, e, nbase, wave, lane, kg, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED)
                    for mi in fx.range_constexpr(BM // 16):
                        ix = (ki * 4 + lane // 16) * BM + mi * 16 + lane % 16
                        av = fx.ptr_load(fx.add_offset(shared, lds_base + ix * 4), result_type=T.i32x4)
                        asc = fx.Int32(fx.ptr_load(fx.add_offset(shared, lds_base + BM * 16 * KSTEP + ix)))
                        for ni in fx.range_constexpr(NR):
                            ai = (mi * NR + ni) * 2
                            accum[ai] = _mfma(av, fx.Vector(operands[ni * 4]), accum[ai], asc, fx.Int32(operands[ni * 4 + 2]))
                            accum[ai + 1] = _mfma(av, fx.Vector(operands[ni * 4 + 1]), accum[ai + 1], asc, fx.Int32(operands[ni * 4 + 3]))
                else:
                    if fx.const_expr(SORTED):
                        if fx.const_expr(LDS):
                            indices = [(ki * 4 + lane // 16) * BM + mi * 16 + lane % 16 for mi in range(BM // 16)]
                            av = [fx.ptr_load(fx.add_offset(shared, lds_base + indices[mi] * 4), result_type=T.i32x4) for mi in range(BM // 16)]
                            asc = [fx.Int32(fx.ptr_load(fx.add_offset(shared, lds_base + BM * 16 * KSTEP + indices[mi]))) for mi in range(BM // 16)]
                        else:
                            indices = [(tile * (D // 32) + kg) * (BM + ROW_PAD) + mi * 16 + lane % 16 for mi in range(BM // 16)]
                            av = [_load4(A, indices[mi] * 4) for mi in range(BM // 16)]
                            asc = [fx.Int32(_load(AS, indices[mi], fx.Uint8)) for mi in range(BM // 16)]
                    else:
                        av = [_load4(A, rows[mi] * (D // 8) + kg * 4) for mi in range(BM // 16)]
                        asc = [fx.Int32(_load(AS, rows[mi] * (D // 32) + kg, fx.Uint8)) for mi in range(BM // 16)]
                    if fx.const_expr(PF):
                        nextkk = ((fx.Int32(kk) + ki) + 1 < D // 128 // PARTS).select((fx.Int32(kk) + ki) + 1, (fx.Int32(kk) + ki))
                        next_w = _w1_operands(W, WS, e, nbase, wave, lane, (nextkk + split * (D // 128 // PARTS)) * 4 + lane // 16, I, D, BN, WAVES, ADDR_BITS, CACHE, PACKED)
                    for ni in fx.range_constexpr(NR):
                        n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
                        if fx.const_expr(PF):
                            wi = ni * 4
                            wg, wu = fx.Vector(current_w[wi]), fx.Vector(current_w[wi + 1])
                            sg, su = fx.Int32(current_w[wi + 2]), fx.Int32(current_w[wi + 3])
                        else:
                            wg = _load4(W, _weight_offset(e, n, kg, 2 * I, D, ADDR_BITS), CACHE)
                            wu = _load4(W, _weight_offset(e, n + I, kg, 2 * I, D, ADDR_BITS), CACHE)
                            sg = _w2_scale(WS, e, n, kg, 2 * I, D, ADDR_BITS, PACKED)
                            su = _w2_scale(WS, e, n + I, kg, 2 * I, D, ADDR_BITS, PACKED)
                        for mi in fx.range_constexpr(BM // 16):
                            ai = (mi * (NR) + ni) * 2
                            accum[ai] = _mfma(av[mi], wg, accum[ai], asc[mi], sg)
                            accum[ai + 1] = _mfma(av[mi], wu, accum[ai + 1], asc[mi], su)
                if fx.const_expr(PF):
                    current_w = next_w
            if fx.const_expr(PF):
                accum = accum + current_w
            if fx.const_expr(APF):
                accum = accum + staged
            result = yield accum
        if fx.const_expr(FUSED_Q and BN // WAVES == 16 and QMAX):
            # Keep the BF16-rounded values in registers. Adjacent waves need
            # only each other's half-group maximum to form the MXFP4 scale.
            values, maxima = [], []
            for mi in fx.range_constexpr(BM // 16):
                gate, up = fx.Vector(result[mi * 2]), fx.Vector(result[mi * 2 + 1])
                for j in fx.range_constexpr(4):
                    local_row = mi * 16 + lane // 16 * 4 + j
                    x = _silu_bf16(gate[j], up[j])
                    a = fx.absf(x)
                    a = _epilogue_reduce(a, EPILOGUE_DPP)
                    values.append(x)
                    maxima.append(a)
                    if lane % 16 == 0:
                        fx.ptr_store(a, fx.add_offset(qshared, local_row * WAVES + wave))
            gpu.barrier()
            for mi in fx.range_constexpr(BM // 16):
                for j in fx.range_constexpr(4):
                    local_row = mi * 16 + lane // 16 * 4 + j
                    row = rb + local_row
                    other = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * WAVES + (wave ^ 1))))
                    a = _max(_max(maxima[mi * 4 + j], other), fx.Float32(1.0e-10))
                    bits = a.bitcast(fx.Int32)
                    exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                    scale = (exponent << 23).bitcast(fx.Float32)
                    x = values[mi * 4 + j]
                    y = fx.Float32(gpu.shuffle_xor(x, 1, 64))
                    q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x, y, scale, 0))
                    kg = (nbase + wave * 16) // 32
                    dst = fx.Int32(0)
                    if fx.const_expr(SORTED):
                        dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                    else:
                        if row < count:
                            rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                            dst = rid * (I // 32) + kg
                    if fx.const_expr(SORTED) or row < count:
                        if lane % 2 == 0:
                            _store(Q, dst * 16 + wave % 2 * 8 + lane % 16 // 2, q, fx.Uint8)
                        if lane % 16 == 0 and wave % 2 == 0:
                            _store(QS, dst, exponent, fx.Uint8)
        elif fx.const_expr(FUSED_Q and BN // WAVES == 16):
            # Each wave owns half of a 32-value MX group.
            # Exchange the BF16-rounded epilogue through padded LDS, then
            # quantize complete groups using 16 lanes per 32 values.
            for mi in fx.range_constexpr(BM // 16):
                gate, up = fx.Vector(result[mi * 2]), fx.Vector(result[mi * 2 + 1])
                for j in fx.range_constexpr(4):
                    local_row = mi * 16 + lane // 16 * 4 + j
                    col = wave * 16 + lane % 16
                    x = _silu_bf16(gate[j], up[j])
                    fx.ptr_store(x, fx.add_offset(qshared, local_row * (BN + 4) + col))
            gpu.barrier()
            for cp in fx.range_constexpr(BM * BN // (2 * THREADS)):
                t = tid + cp * THREADS
                local_row, col = t // (BN // 2), t % (BN // 2) * 2
                row = rb + local_row
                x0 = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * (BN + 4) + col)))
                x1 = fx.Float32(fx.ptr_load(fx.add_offset(qshared, local_row * (BN + 4) + col + 1)))
                a = _max(fx.absf(x0), fx.absf(x1))
                a = _epilogue_reduce(a, EPILOGUE_DPP)
                a = _max(a, fx.Float32(1.0e-10))
                bits = a.bitcast(fx.Int32)
                exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                scale = (exponent << 23).bitcast(fx.Float32)
                q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                kg = (nbase + col) // 32
                dst = fx.Int32(0)
                if fx.const_expr(SORTED):
                    dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                else:
                    if row < count:
                        rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                        dst = rid * (I // 32) + kg
                if fx.const_expr(SORTED) or row < count:
                    _store(Q, dst * 16 + col % 32 // 2, q, fx.Uint8)
                    if col % 32 == 0:
                        _store(QS, dst, exponent, fx.Uint8)
        elif fx.const_expr(FUSED_Q):
            # Two adjacent 16-column fragments share one MXFP4 scale. Each
            # 16-lane subgroup owns all 32 values of one output row.
            for mi in fx.range_constexpr(BM // 16):
                for ni in fx.range_constexpr(BN // (WAVES * 32)):
                    ai = (mi * (NR) + ni * 2) * 2
                    gate0, up0 = fx.Vector(result[ai]), fx.Vector(result[ai + 1])
                    gate1, up1 = fx.Vector(result[ai + 2]), fx.Vector(result[ai + 3])
                    kg = (nbase + wave * (BN // WAVES)) // 32 + ni
                    for j in fx.range_constexpr(4):
                        local_row = mi * 16 + lane // 16 * 4 + j
                        row = rb + local_row
                        x0 = _silu_bf16(gate0[j], up0[j])
                        x1 = _silu_bf16(gate1[j], up1[j])
                        a = _max(fx.absf(x0), fx.absf(x1))
                        a = _epilogue_reduce(a, EPILOGUE_DPP)
                        a = _max(a, fx.Float32(1.0e-10))
                        bits = a.bitcast(fx.Int32)
                        exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                        scale = (exponent << 23).bitcast(fx.Float32)
                        y0 = fx.Float32(gpu.shuffle_xor(x0, 1, 64))
                        y1 = fx.Float32(gpu.shuffle_xor(x1, 1, 64))
                        q0 = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, y0, scale, 0))
                        q1 = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x1, y1, scale, 0))
                        dst = fx.Int32(0)
                        if fx.const_expr(SORTED):
                            dst = (tile * (I // 32) + kg) * (BM + ROW_PAD) + local_row
                        else:
                            if row < count:
                                rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                                dst = rid * (I // 32) + kg
                        if fx.const_expr(SORTED) or row < count:
                            if lane % 2 == 0:
                                if fx.const_expr(QSHUFFLE):
                                    local_kg = wave * (BN // WAVES // 32) + ni
                                    qoff = (local_kg * BM + local_row) * 16 + lane % 16 // 2
                                    fx.ptr_store(fx.Uint8(q0), fx.add_offset(qbytes, qoff))
                                    fx.ptr_store(fx.Uint8(q1), fx.add_offset(qbytes, qoff + 8))
                                else:
                                    _store(Q, dst * 16 + lane % 16 // 2, q0, fx.Uint8)
                                    _store(Q, dst * 16 + lane % 16 // 2 + 8, q1, fx.Uint8)
                            if lane % 16 == 0:
                                _store(QS, dst, exponent, fx.Uint8)
            if fx.const_expr(QSHUFFLE):
                # One lane writes one complete packed scale group, in the
                # tile-major layout read by the second projection.
                gpu.barrier()
                for cp in fx.range_constexpr((BM * (BN // 32) + THREADS - 1) // THREADS):
                    qi = tid + cp * THREADS
                    if qi < BM * (BN // 32):
                        local_kg, local_row = qi // BM, qi % BM
                        dst = (tile * (I // 32) + nbase // 32 + local_kg) * (BM + ROW_PAD) + local_row
                        qv = fx.ptr_load(fx.add_offset(qwords, qi * 4), result_type=T.i32x4)
                        fx.ptr_store(qv, fx.add_offset(_ptr(Q, fx.Int32, 16), dst * 4))
        else:
            for mi in fx.range_constexpr(BM // 16):
                for ni in fx.range_constexpr(NR):
                    ai = (mi * (NR) + ni) * 2
                    gate = fx.Vector(result[ai])
                    up = fx.Vector(result[ai + 1])
                    n = nbase + wave * (BN // WAVES) + ni * 16 + lane % 16
                    for j in fx.range_constexpr(4):
                        row = rb + mi * 16 + lane // 16 * 4 + j
                        if row < count:
                            rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                            if fx.const_expr(PARTS > 1):
                                _store(H, (split * 2) * R * I + rid * I + n, gate[j], fx.Float32)
                                _store(H, (split * 2 + 1) * R * I + rid * I + n, up[j], fx.Float32)
                            else:
                                g = gate[j]
                                exp_neg = fx.Float32(rocdl.exp2(T.f32, fx.Float32(-g * fx.Float32(1.4426950408889634)).ir_value()))
                                inv = fx.Float32(rocdl.rcp(T.f32, fx.Float32(fx.Float32(1.0) + exp_neg).ir_value()))
                                val = (g * inv) * up[j]
                                _store(H, rid * I + n, val, fx.BFloat16)


@flyc.kernel
def _gemm2(A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
           Routes: fx.Int64, Counts: fx.Int64, TileE: fx.Int64, TileR: fx.Int64,
           Total: fx.Int64, P: fx.Int64, Local: fx.Int64,
           R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int], TOPK: fx.Constexpr[int], OUT: fx.Constexpr[bool],
           BM: fx.Constexpr[int], BN: fx.Constexpr[int], SORTED: fx.Constexpr[bool], LDS: fx.Constexpr[bool], PF: fx.Constexpr[bool], BF16_P: fx.Constexpr[bool], FP8_P: fx.Constexpr[bool], DIRECT: fx.Constexpr[bool], KSTEP: fx.Constexpr[int], WIDE: fx.Constexpr[bool], ADDR_BITS: fx.Constexpr[bool], GROUP_M: fx.Constexpr[int], CSHUFFLE: fx.Constexpr[bool], ROW_PAD: fx.Constexpr[int], CACHE: fx.Constexpr[int], PACKED: fx.Constexpr[bool], ROW_MAJOR: fx.Constexpr[bool], SPLIT: fx.Constexpr[int], APF: fx.Constexpr[bool]):
    # SPLIT row tiles of BM share one activation tile of BM * SPLIT rows.
    FRAG = 32 if WIDE else 16
    ELEMENTS = 16 if WIDE else 4
    NR = BN // (FRAG * 4)
    KFACTOR = 2 if WIDE else 1
    EBYTES = 1 if FP8_P else (2 if BF16_P else 4)
    ESTRIDE = BN * EBYTES + 16
    ETYPE = fx.Uint8 if FP8_P else (fx.BFloat16 if BF16_P else fx.Float32)
    pid = fx.Int32(fx.block_idx.x)
    bound = fx.Int32(R * (D // BN))
    if fx.const_expr(not DIRECT):
        bound = _load(Total, 0) * SPLIT * (D // BN)
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    smem = fx.SharedAllocator()
    if fx.const_expr(LDS):
        shared = fx.recast_iter(fx.Int32, smem.allocate(BM * 4 * 20 * KSTEP, alignment=16).peek().ptr)
    if fx.const_expr(CSHUFFLE):
        eptr = smem.allocate(BM * ESTRIDE, alignment=16).peek().ptr
        evalues = fx.recast_iter(ETYPE, eptr)
        ewords = fx.recast_iter(fx.Int32, eptr)
    if pid < bound:
        ordered = _chiplet_order(pid, bound)
        tile = ordered // (D // BN)
        nbase = ordered % (D // BN) * BN
        e = _load(TileE, tile // SPLIT)
        rb, count = fx.Int32(0), fx.Int32(1)
        if fx.const_expr(not DIRECT):
            rb = _load(TileR, tile // SPLIT) + tile % SPLIT * BM
            count = _load(Counts, e)
        if fx.const_expr(GROUP_M > 1):
            member = (rb // BM) % GROUP_M
            first_row = rb - member * BM
            if first_row + (GROUP_M - 1) * BM < count:
                local = member * (D // BN) + ordered % (D // BN)
                tile = tile - member + local % GROUP_M
                rb = first_row + (local % GROUP_M) * BM
                nbase = (local // GROUP_M) * BN
        if rb < count:
            rows = []
            for mi in fx.range_constexpr(BM // FRAG):
                row = rb + mi * FRAG + lane % FRAG
                rid = fx.Int32(0)
                if row < count:
                    rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                rows.append(rid)
            zeros = [fx.Vector.filled(ELEMENTS, 0.0, fx.Float32) for _ in range(BM // FRAG * NR)]
            if fx.const_expr(PF):
                zeros = zeros + _w2_operands(W, WS, e, nbase, wave, lane, lane // FRAG, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED)
            WEND = len(zeros)
            if fx.const_expr(APF):
                # The next activation step is loaded while this one computes.
                zeros = zeros + _a_chunk(A, AS, tile, fx.Int32(0), tid, BM, KSTEP, SPLIT, I)
            for kk, state in range(0, I // 128, KSTEP, init=zeros):
                if fx.const_expr(APF):
                    gpu.barrier()
                    staged = state[WEND:]
                    for cp in fx.range_constexpr(len(staged) // 2):
                        ix = tid + cp * 256
                        fx.ptr_store(fx.Vector(staged[cp * 2]), fx.add_offset(shared, ix * 4))
                        fx.ptr_store(fx.Int32(staged[cp * 2 + 1]), fx.add_offset(shared, BM * 16 * KSTEP + ix))
                    following = (fx.Int32(kk) + KSTEP < I // 128).select(fx.Int32(kk) + KSTEP, fx.Int32(kk))
                    staged = _a_chunk(A, AS, tile, following, tid, BM, KSTEP, SPLIT, I)
                    gpu.barrier()
                elif fx.const_expr(SORTED and LDS):
                    gpu.barrier()
                    for cp in fx.range_constexpr((BM * 4 * KSTEP + 255) // 256):
                        ix = tid + cp * 256
                        if ix < BM * 4 * KSTEP:
                            gi = (tile // SPLIT * (I // 32) + fx.Int32(kk) * 4 + ix // BM) * (BM * SPLIT) + tile % SPLIT * BM + ix % BM
                            if fx.const_expr(ROW_PAD != 0):
                                gi = (tile * (I // 32) + fx.Int32(kk) * 4 + ix // BM) * (BM + ROW_PAD) + ix % BM
                            vv = _load4(A, gi * 4)
                            ss = fx.Int32(_load(AS, gi, fx.Uint8))
                            fx.ptr_store(vv, fx.add_offset(shared, ix * 4))
                            fx.ptr_store(ss, fx.add_offset(shared, BM * 16 * KSTEP + ix))
                    gpu.barrier()
                accum = [fx.Vector(x) for x in state[:BM // FRAG * NR]]
                if fx.const_expr(PF):
                    current_w = state[BM // FRAG * NR:WEND]
                for ki in fx.range_constexpr(KSTEP * KFACTOR):
                    kg = fx.Int32(kk) * 4 + ki * (4 // KFACTOR) + lane // FRAG
                    if fx.const_expr(ROW_MAJOR):
                        # Retain the two weight fragments while streaming one
                        # activation row fragment at a time through the accumulators.
                        operands = _w2_operands(W, WS, e, nbase, wave, lane, kg, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED)
                        for mi in fx.range_constexpr(BM // FRAG):
                            ix = (ki * (4 // KFACTOR) + lane // FRAG) * BM + mi * FRAG + lane % FRAG
                            av = fx.ptr_load(fx.add_offset(shared, ix * 4), result_type=T.i32x4)
                            asc = fx.Int32(fx.ptr_load(fx.add_offset(shared, BM * 16 * KSTEP + ix)))
                            for ni in fx.range_constexpr(NR):
                                ai = mi * NR + ni
                                accum[ai] = _mfma2(av, fx.Vector(operands[ni * 2]), accum[ai], asc, fx.Int32(operands[ni * 2 + 1]), WIDE)
                    else:
                        if fx.const_expr(SORTED):
                            if fx.const_expr(LDS):
                                indices = [(ki * (4 // KFACTOR) + lane // FRAG) * BM + mi * FRAG + lane % FRAG for mi in range(BM // FRAG)]
                                av = [fx.ptr_load(fx.add_offset(shared, indices[mi] * 4), result_type=T.i32x4) for mi in range(BM // FRAG)]
                                asc = [fx.Int32(fx.ptr_load(fx.add_offset(shared, BM * 16 * KSTEP + indices[mi]))) for mi in range(BM // FRAG)]
                            else:
                                indices = [(tile * (I // 32) + kg) * (BM + ROW_PAD) + mi * FRAG + lane % FRAG for mi in range(BM // FRAG)]
                                av = [_load4(A, indices[mi] * 4) for mi in range(BM // FRAG)]
                                asc = [fx.Int32(_load(AS, indices[mi], fx.Uint8)) for mi in range(BM // FRAG)]
                        else:
                            av = [_load4(A, rows[mi] * (I // 8) + kg * 4) for mi in range(BM // FRAG)]
                            asc = [fx.Int32(_load(AS, rows[mi] * (I // 32) + kg, fx.Uint8)) for mi in range(BM // FRAG)]
                        if fx.const_expr(PF):
                            nextkk = (fx.Int32(kk) * KFACTOR + ki + 1 < I // (128 // KFACTOR)).select(fx.Int32(kk) * KFACTOR + ki + 1, fx.Int32(kk) * KFACTOR + ki)
                            next_w = _w2_operands(W, WS, e, nbase, wave, lane, nextkk * (4 // KFACTOR) + lane // FRAG, D, I, BN, FRAG, ADDR_BITS, CACHE, PACKED)
                        for ni in fx.range_constexpr(NR):
                            n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
                            if fx.const_expr(PF):
                                wi = ni * 2
                                w, s = fx.Vector(current_w[wi]), fx.Int32(current_w[wi + 1])
                            else:
                                w = _load4(W, _weight_offset(e, n, kg, D, I, ADDR_BITS), CACHE)
                                s = _w2_scale(WS, e, n, kg, D, I, ADDR_BITS, PACKED)
                            for mi in fx.range_constexpr(BM // FRAG):
                                ai = mi * (NR) + ni
                                accum[ai] = _mfma2(av[mi], w, accum[ai], asc[mi], s, WIDE)
                    if fx.const_expr(PF):
                        current_w = next_w
                if fx.const_expr(PF):
                    accum = accum + current_w
                if fx.const_expr(APF):
                    accum = accum + staged
                result = yield accum
            if fx.const_expr(BM // FRAG * NR == 1 and not PF and not APF):
                result = [result]
            for mi in fx.range_constexpr(BM // FRAG):
                for ni in fx.range_constexpr(NR):
                    acc = fx.Vector(result[mi * (NR) + ni])
                    n = nbase + wave * (BN // 4) + ni * FRAG + lane % FRAG
                    for j in fx.range_constexpr(ELEMENTS):
                        row = rb + mi * FRAG + lane // FRAG * 4 + j
                        if fx.const_expr(WIDE):
                            # A 32x32 fragment returns four groups of four rows.
                            row = rb + mi * FRAG + lane // FRAG * 4 + (j // 4) * 8 + j % 4
                        if fx.const_expr(CSHUFFLE):
                            ecol = wave * (BN // 4) + ni * FRAG + lane % FRAG
                            if fx.const_expr(FP8_P):
                                epacked = fx.Int32(rocdl.cvt_pk_fp8_f32(T.i32, acc[j], acc[j], fx.Int32(0), False))
                                fx.ptr_store(fx.Uint8(epacked), fx.add_offset(evalues, (row - rb) * (ESTRIDE // EBYTES) + ecol))
                            else:
                                fx.ptr_store(ETYPE(acc[j]), fx.add_offset(evalues, (row - rb) * (ESTRIDE // EBYTES) + ecol))
                        elif row < count:
                            rid = _routed_row(Routes, e * R + row, tile, DIRECT)
                            if fx.const_expr(FP8_P):
                                packed = fx.Int32(rocdl.cvt_pk_fp8_f32(T.i32, acc[j], acc[j], fx.Int32(0), False))
                                _store(P, rid * D + n, packed, fx.Uint8)
                            elif fx.const_expr(BF16_P):
                                _store(P, rid * D + n, acc[j], fx.BFloat16)
                            else:
                                _store(P, rid * D + n, acc[j], fx.Float32)
            if fx.const_expr(CSHUFFLE and OUT):
                # P is the output; tokens with one local route own their row,
                # others were zeroed earlier and are summed atomically. Row
                # lookups are issued before the shuffle barrier.
                COPIES = (BM * BN * EBYTES + 4095) // 4096
                targets = []
                for cp in fx.range_constexpr(COPIES):
                    pos = (tid + cp * 256) * 16
                    local_row = pos // (BN * EBYTES)
                    valid = (local_row < BM) & (rb + local_row < count)
                    rid = valid.select(_load(Routes, valid.select(e * R + rb + local_row, fx.Int32(0))), fx.Int32(0))
                    targets.append((valid, rid))
                targets = [(valid, rid // TOPK, fx.Float32(1.0), _local_routes(Local, rid // TOPK, TOPK)) for valid, rid in targets]
                gpu.barrier()
                for cp in fx.range_constexpr(COPIES):
                    pos = (tid + cp * 256) * 16
                    local_row, local_col = pos // (BN * EBYTES), pos % (BN * EBYTES)
                    valid, token, weight, n = targets[cp]
                    if valid:
                        v = fx.ptr_load(fx.add_offset(ewords, (local_row * ESTRIDE + local_col) // 4), result_type=T.i32x4)
                        halves = fx.Vector(v).bitcast(fx.BFloat16)
                        scaled = [weight * fx.Float32(halves[j]) for j in range(8)]
                        offset = token * D + nbase + local_col // 2
                        if n == 1:
                            output = fx.Vector.from_elements([fx.BFloat16(x) for x in scaled])
                            fx.ptr_store(output, fx.add_offset(_ptr(P, fx.BFloat16, 16), offset))
                        if n != 1:
                            for h in fx.range_constexpr(4):
                                _atomic_add_bf16x2(P, offset // 2 + h, scaled[2 * h], scaled[2 * h + 1])
            elif fx.const_expr(CSHUFFLE):
                gpu.barrier()
                for cp in fx.range_constexpr((BM * BN * EBYTES + 4095) // 4096):
                    pos = (tid + cp * 256) * 16
                    local_row, local_col = pos // (BN * EBYTES), pos % (BN * EBYTES)
                    if local_row < BM and rb + local_row < count:
                        rid = _routed_row(Routes, e * R + rb + local_row, tile, DIRECT)
                        v = fx.ptr_load(fx.add_offset(ewords, (local_row * ESTRIDE + local_col) // 4), result_type=T.i32x4)
                        fx.ptr_store(v, fx.add_offset(_ptr(P, fx.Int32, 16), ((rid * D + nbase) * EBYTES + local_col) // 4))




def _atomic_add(pointer, value):
    return fx.Int32(llvm.atomicrmw(llvm.AtomicBinOp.add, fx.to_llvm_ptr(pointer), fx.Int32(value).ir_value(), llvm.AtomicOrdering.monotonic))


def _a_chunk(A, AS, tile, kk, tid, BM, KSTEP, SPLIT, K):
    # One K step of a sorted MXFP4 activation tile, as loaded registers.
    values = []
    for cp in range((BM * 4 * KSTEP + 255) // 256):
        ix = tid + cp * 256
        gi = (tile // SPLIT * (K // 32) + kk * 4 + ix // BM) * (BM * SPLIT) + tile % SPLIT * BM + ix % BM
        values += [_load4(A, gi * 4), fx.Int32(_load(AS, gi, fx.Uint8))]
    return values


def _atomic_add_bf16x2(Out, index, low, high):
    pair = fx.Vector.from_elements([fx.BFloat16(low), fx.BFloat16(high)])
    pointer = fx.to_llvm_ptr(fx.add_offset(_ptr(Out, fx.Int32), index))
    llvm.atomicrmw(llvm.AtomicBinOp.fadd, pointer, pair.ir_value(), llvm.AtomicOrdering.monotonic, syncscope="agent")


def _local_routes(Local, token, TOPK):
    # Local holds a slot or -1, so sign bits count the routes off this rank.
    n = fx.Int32(TOPK)
    for k in range(TOPK):
        n = n + (_load(Local, token * TOPK + k) >> 31)
    return n


@flyc.kernel
def _clear(Counts: fx.Int64, E: fx.Constexpr[int]):
    tid = fx.Int32(fx.thread_idx.x)
    if tid < E:
        _store(Counts, tid, 0)


@flyc.kernel
def _route_masked(Ids: fx.Int64, Mask: fx.Int64, Counts: fx.Int64, Routes: fx.Int64, Local: fx.Int64,
                  R: fx.Constexpr[int], E: fx.Constexpr[int], G: fx.Constexpr[int],
                  CHUNKS: fx.Constexpr[int], MULTI: fx.Constexpr[bool]):
    # Global expert ids map to local slots through the mask's prefix sum; other
    # ranks' experts and the padding slot map to -1. Ranks within a workgroup
    # come from LDS atomics, so routes within an expert are in no fixed order.
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    smem = fx.SharedAllocator()
    slots = fx.recast_iter(fx.Int32, smem.allocate(G * 4, alignment=16).peek().ptr)
    totals = fx.recast_iter(fx.Int32, smem.allocate(16 * 4, alignment=16).peek().ptr)
    hist = fx.recast_iter(fx.Int32, smem.allocate(E * 4, alignment=16).peek().ptr)
    bases = fx.recast_iter(fx.Int32, smem.allocate(E * 4, alignment=16).peek().ptr)
    flag = fx.Int32(0)
    if tid < G:
        flag = _load(Mask, tid)
    flag = (flag != 0).select(fx.Int32(1), fx.Int32(0))
    prefix = _prefix64(flag, lane)
    if lane == 63:
        fx.ptr_store(prefix, fx.add_offset(totals, wave))
    if tid < E:
        fx.ptr_store(fx.Int32(0), fx.add_offset(hist, tid))
    gpu.barrier()
    for w in fx.range_constexpr(15):
        earlier = fx.Int32(fx.ptr_load(fx.add_offset(totals, w)))
        prefix = prefix + (wave > w).select(earlier, fx.Int32(0))
    if tid < G:
        fx.ptr_store((flag != 0).select(prefix - 1, fx.Int32(-1)), fx.add_offset(slots, tid))
    gpu.barrier()
    first = fx.Int32(fx.block_idx.x) * (CHUNKS * 1024)
    experts, ranks = [], []
    for c in fx.range_constexpr(CHUNKS):
        r = first + c * 1024 + tid
        e = fx.Int32(-1)
        if r < R:
            e = fx.Int32(fx.ptr_load(fx.add_offset(slots, _pair_id(Ids, r, G))))
            _store(Local, r, e)
        rank = fx.Int32(0)
        if e >= 0:
            rank = _atomic_add(fx.add_offset(hist, e), 1)
        experts.append(e)
        ranks.append(rank)
    gpu.barrier()
    if tid < E:
        count = fx.Int32(fx.ptr_load(fx.add_offset(hist, tid)))
        if fx.const_expr(MULTI):
            base = fx.Int32(0)
            if count > 0:
                base = _atomic_add(fx.add_offset(_ptr(Counts, fx.Int32), tid), count)
            fx.ptr_store(base, fx.add_offset(bases, tid))
        else:
            _store(Counts, tid, count)
    if fx.const_expr(MULTI):
        gpu.barrier()
    for c in fx.range_constexpr(CHUNKS):
        e = experts[c]
        if e >= 0:
            position = ranks[c]
            if fx.const_expr(MULTI):
                position = position + fx.Int32(fx.ptr_load(fx.add_offset(bases, e)))
            _store(Routes, e * R + position, first + c * 1024 + tid)


@flyc.kernel
def _gather_input(X: fx.Int64, B: fx.Int64, BS: fx.Int64, Routes: fx.Int64, Counts: fx.Int64,
                  TE: fx.Int64, TR: fx.Int64, Total: fx.Int64, Local: fx.Int64, Out: fx.Int64,
                  M: fx.Constexpr[int], ZERO: fx.Constexpr[bool], R: fx.Constexpr[int], D: fx.Constexpr[int], TOPK: fx.Constexpr[int],
                  BM: fx.Constexpr[int], E: fx.Constexpr[int], BLOCKS: fx.Constexpr[int],
                  UNROLL: fx.Constexpr[int], SHARED_N: fx.Constexpr[int],
                  Ids: fx.Int64, Mask: fx.Int64, G: fx.Constexpr[int], FUSED: fx.Constexpr[bool],
                  Wn: fx.Int64, REP: fx.Constexpr[int], EPS: fx.Constexpr[int], GAIN: fx.Constexpr[int]):
    # Normalize and quantize only the routed rows, straight into the tile-major
    # MXFP4 layout of the first projection. A fixed grid walks the live tiles' rows.
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    bid = fx.Int32(fx.block_idx.x)
    smem = fx.SharedAllocator()
    red = fx.recast_iter(fx.Float32, smem.allocate(UNROLL * 4 * 4, alignment=16).peek().ptr)
    gains = _norm_gains(Wn, tid, D // 2048, GAIN)
    if fx.const_expr(FUSED):
        # Every workgroup routes all R ids itself and writes the Routes entries
        # of the rows it gathers.
        slots = fx.recast_iter(fx.Int32, smem.allocate(G * 4, alignment=16).peek().ptr)
        hist = fx.recast_iter(fx.Int32, smem.allocate(64 * 4, alignment=16).peek().ptr)
        counts = fx.recast_iter(fx.Int32, smem.allocate(E * 64 * 4, alignment=16).peek().ptr)
        table = fx.recast_iter(fx.Int32, smem.allocate(R * 4, alignment=16).peek().ptr)
        if wave == 0:
            running = fx.Int32(0)
            for c in fx.range_constexpr((G + 63) // 64):
                g = c * 64 + lane
                flag = fx.Int32(0)
                if g < G:
                    flag = _load(Mask, g)
                flag = (flag != 0).select(fx.Int32(1), fx.Int32(0))
                prefix = _prefix64(flag, lane) + running
                if g < G:
                    fx.ptr_store((flag != 0).select(prefix - 1, fx.Int32(-1)), fx.add_offset(slots, g))
                running = fx.Int32(gpu.shuffle_idx(prefix, 63, 64))
        gpu.barrier()
        # Ranks follow route order: ballots rank within a wave, and an LDS scan
        # over (chunk, wave) per expert supplies the offsets.
        CH = (R + 255) // 256
        below = (fx.Uint64(1) << fx.Uint64(lane)) - fx.Uint64(1)
        experts, ranks = [], []
        for c in fx.range_constexpr(CH):
            r = c * 256 + tid
            e = fx.Int32(-1)
            if r < R:
                e = fx.Int32(fx.ptr_load(fx.add_offset(slots, _pair_id(Ids, r, G))))
                if bid == 0:
                    _store(Local, r, e)
            rank = fx.Int32(0)
            for x in fx.range_constexpr(E):
                hits = fx.Uint64(rocdl.ballot(T.i64, e == x))
                if lane == 0:
                    fx.ptr_store(fx.Int32(fx.ctpop(hits)), fx.add_offset(counts, x * 64 + c * 4 + wave))
                rank = (e == x).select(fx.Int32(fx.ctpop(hits & below)), rank)
            experts.append(e)
            ranks.append(rank)
        gpu.barrier()
        for xi in fx.range_constexpr((E + 3) // 4):
            x = xi * 4 + wave
            if x < E:
                v = fx.Int32(0)
                if lane < CH * 4:
                    v = fx.Int32(fx.ptr_load(fx.add_offset(counts, x * 64 + lane)))
                inclusive = _prefix64(v, lane)
                if lane < CH * 4:
                    fx.ptr_store(inclusive - v, fx.add_offset(counts, x * 64 + lane))
                if lane == 63:
                    fx.ptr_store(inclusive, fx.add_offset(hist, x))
        gpu.barrier()
        count = (lane < E).select(fx.Int32(fx.ptr_load(fx.add_offset(hist, (lane < E).select(lane, fx.Int32(0))))), fx.Int32(0))
        base = _prefix64(count, lane) - count
        if (bid == 0) & (tid < E):
            _store(Counts, tid, count)
        for c in fx.range_constexpr(CH):
            e = experts[c]
            safe = (e >= 0).select(e, fx.Int32(0))
            start = fx.Int32(gpu.shuffle_idx(base, safe, 64))
            offset = fx.Int32(fx.ptr_load(fx.add_offset(counts, safe * 64 + c * 4 + wave)))
            if e >= 0:
                fx.ptr_store(c * 256 + tid, fx.add_offset(table, start + offset + ranks[c]))
        gpu.barrier()
    else:
        count = _load(Counts, (lane < E).select(lane, fx.Int32(0)))
    tiles = (lane < E).select((count + BM - 1) // BM, fx.Int32(0))
    prefix = _prefix64(tiles, lane)
    total = fx.Int32(gpu.shuffle_idx(prefix, 63, 64))
    if bid == 0 and tid == 0:
        _store(Total, 0, total)
    HALVES = D // 2048
    if fx.const_expr(ZERO):
        # Rows without exactly one local route are accumulated atomically later.
        # With SHARED_N the first projection's total * SHARED_N blocks clear up
        # to 64 rows each instead.
        for it in fx.range_constexpr((M + BLOCKS - 1) // BLOCKS):
            token = bid + it * BLOCKS
            if (token < M) & (fx.Int32(M) > total * (SHARED_N * 64)):
                n_local = fx.Int32(0)
                if fx.const_expr(FUSED):
                    n_local = fx.Int32(TOPK)
                    for k in fx.range_constexpr(TOPK):
                        n_local = n_local + (fx.Int32(fx.ptr_load(fx.add_offset(slots, _pair_id(Ids, token * TOPK + k, G)))) >> 31)
                else:
                    n_local = _local_routes(Local, token, TOPK)
                if n_local != 1:
                    zero = fx.Vector.filled(4, 0, fx.Int32)
                    for h in fx.range_constexpr(HALVES):
                        fx.ptr_store(zero, fx.add_offset(_ptr(Out, fx.Int32, 16), (token * (D // 8) + h * 256 + tid) * 4))
    # Every load of an iteration is issued before its quantization; padding
    # rows read token 0 and store nothing.
    for it in range((total * BM - bid + BLOCKS * UNROLL - 1) // (BLOCKS * UNROLL)):
        rows, targets = [], []
        for u in fx.range_constexpr(UNROLL):
            unit = bid + (fx.Int32(it) * UNROLL + u) * BLOCKS
            tile, row = unit // BM, unit % BM
            mask = fx.Uint64(rocdl.ballot(T.i64, prefix > tile))
            expert = fx.Int32(64) - fx.Int32(fx.ctpop(mask))
            expert = (expert < E).select(expert, fx.Int32(0))
            end = fx.Int32(gpu.shuffle_idx(prefix, expert, 64))
            length = fx.Int32(gpu.shuffle_idx(tiles, expert, 64))
            live = fx.Int32(gpu.shuffle_idx(count, expert, 64))
            first_row = (tile - end + length) * BM
            if row == 0 and tid == 0 and tile < total:
                _store(TE, tile, expert)
                _store(TR, tile, first_row)
            valid = (tile < total) & (first_row + row < live)
            index = valid.select(expert * R + first_row + row, fx.Int32(0))
            if fx.const_expr(FUSED):
                start = fx.Int32(gpu.shuffle_idx(base, expert, 64))
                targets.append(expert * R + first_row + row)
                index = valid.select(start + first_row + row, fx.Int32(0))
            rows.append((tile, row, valid, index))
        if fx.const_expr(FUSED):
            rids = [fx.Int32(fx.ptr_load(fx.add_offset(table, index))) for (_, _, _, index) in rows]
            for u in fx.range_constexpr(UNROLL):
                if rows[u][2] & (tid == 0):
                    _store(Routes, targets[u], rids[u])
        else:
            rids = [_load(Routes, index) for (_, _, _, index) in rows]
        tokens = [valid.select(rid // TOPK // REP, fx.Int32(0)) for rid, (_, _, valid, _) in zip(rids, rows)]
        loaded = [[_load4(X, (token * (D // 8) + h * 256 + tid) * 4) for h in range(HALVES)] for token in tokens]
        normalized = _normalize_rows(loaded, gains, red, tid, D, EPS)
        for u in fx.range_constexpr(UNROLL):
            tile, row, valid, _ = rows[u]
            for h in fx.range_constexpr(HALVES):
                packed, exponent = _quantize_values(normalized[u][h])
                c8 = h * 256 + tid
                if valid:
                    dst = (tile * (D // 32) + c8 // 4) * BM + row
                    _store(B, dst * 4 + c8 % 4, packed)
                    if c8 % 4 == 0:
                        _store(BS, dst, exponent, fx.Uint8)


@flyc.kernel
def _route_gather(X: fx.Int64, B: fx.Int64, BS: fx.Int64, Ids: fx.Int64, Mask: fx.Int64,
                  Counts: fx.Int64, Routes: fx.Int64, Local: fx.Int64, Out: fx.Int64,
                  M: fx.Constexpr[int], ZERO: fx.Constexpr[bool], R: fx.Constexpr[int], D: fx.Constexpr[int],
                  TOPK: fx.Constexpr[int], BM: fx.Constexpr[int], E: fx.Constexpr[int], G: fx.Constexpr[int],
                  RPB: fx.Constexpr[int],
                  Wn: fx.Int64, REP: fx.Constexpr[int], EPS: fx.Constexpr[int], GAIN: fx.Constexpr[int]):
    # Route and gather in one launch. Workgroup b owns routes [b * RPB, (b + 1) * RPB):
    # every workgroup counts all R routes per local expert, and those before its own,
    # so a route's row in its expert follows route order without a separate pass.
    # Every global load that does not depend on the routing is issued first.
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    start = fx.Int32(fx.block_idx.x) * RPB
    smem = fx.SharedAllocator()
    slots = fx.recast_iter(fx.Int32, smem.allocate(G * 4, alignment=16).peek().ptr)
    # hist[e] counts expert e's routes in its low half and those before `start` in its high half;
    # off-rank routes add to 64 spare words, so no lane waits on a branch or a shared word.
    hist = fx.recast_iter(fx.Int32, smem.allocate((E + 64) * 4, alignment=16).peek().ptr)
    GC = (G + 255) // 256
    totals = fx.recast_iter(fx.Int32, smem.allocate(GC * 4 * 4, alignment=16).peek().ptr)
    RC = (R + 255) // 256
    red = fx.recast_iter(fx.Float32, smem.allocate(RPB * 4 * 4, alignment=16).peek().ptr)
    gains = _norm_gains(Wn, tid, D // 2048, GAIN)
    flags = []
    for c in fx.range_constexpr(GC):
        flag = fx.Int32(0)
        if c * 256 + tid < G:
            flag = _load(Mask, c * 256 + tid)
        flags.append((flag != 0).select(fx.Int32(1), fx.Int32(0)))
    ids = []
    for c in fx.range_constexpr(RC):
        if fx.const_expr((c + 1) * 256 <= R):
            ids.append(_pair_id(Ids, c * 256 + tid, G))
        else:
            v = fx.Int32(G - 1)
            if c * 256 + tid < R:
                v = _pair_id(Ids, c * 256 + tid, G)
            ids.append(v)
    own = []
    for u in fx.range_constexpr(RPB):
        v = fx.Int32(0)
        if start + u < R:
            v = _pair_id(Ids, start + u, G)
        own.append(v)
    prefixes = []
    for c in fx.range_constexpr(GC):
        prefix = _prefix64(flags[c], lane)
        if lane == 63:
            fx.ptr_store(prefix, fx.add_offset(totals, c * 4 + wave))
        prefixes.append(prefix)
    if tid < E + 64:
        fx.ptr_store(fx.Int32(0), fx.add_offset(hist, tid))
    gpu.barrier()
    for c in fx.range_constexpr(GC):
        prefix = prefixes[c]
        for w in fx.range_constexpr(c * 4 + 3):
            earlier = fx.Int32(fx.ptr_load(fx.add_offset(totals, w)))
            if fx.const_expr(w < c * 4):
                prefix = prefix + earlier
            else:
                prefix = prefix + (wave > w - c * 4).select(earlier, fx.Int32(0))
        if c * 256 + tid < G:
            fx.ptr_store((flags[c] != 0).select(prefix - 1, fx.Int32(-1)), fx.add_offset(slots, c * 256 + tid))
    gpu.barrier()
    routed = [fx.Int32(fx.ptr_load(fx.add_offset(slots, ids[c]))) for c in range(RC)]
    for c in fx.range_constexpr(RC):
        e = routed[c]
        _atomic_add(fx.add_offset(hist, (e >= 0).select(e, E + lane)), (c * 256 + tid < start).select(fx.Int32(0x10001), fx.Int32(1)))
    experts = [fx.Int32(fx.ptr_load(fx.add_offset(slots, own[u]))) for u in range(RPB)]
    for u in fx.range_constexpr(RPB):
        if start + u >= R:
            experts[u] = fx.Int32(-1)
    HALVES = D // 2048
    loaded = []
    for u in fx.range_constexpr(RPB):
        token = (experts[u] >= 0).select((start + u) // TOPK // REP, fx.Int32(0))
        loaded.append([_load4(X, (token * (D // 8) + h * 256 + tid) * 4) for h in range(HALVES)])
    if fx.const_expr(ZERO):
        # Tokens with no or several local routes are summed atomically (or stay zero).
        for t in fx.range_constexpr(RPB // TOPK):
            n_local = fx.Int32(0)
            for k in fx.range_constexpr(TOPK):
                n_local = n_local + (experts[t * TOPK + k] >= 0).select(fx.Int32(1), fx.Int32(0))
            token = start // TOPK + t
            if (n_local != 1) & (token < M):
                zero = fx.Vector.filled(4, 0, fx.Int32)
                for h in fx.range_constexpr(HALVES):
                    fx.ptr_store(zero, fx.add_offset(_ptr(Out, fx.Int32, 16), (token * (D // 8) + h * 256 + tid) * 4))
    normalized = _normalize_rows(loaded, gains, red, tid, D, EPS)
    packed_count = (lane < E).select(fx.Int32(fx.ptr_load(fx.add_offset(hist, (lane < E).select(lane, fx.Int32(0))))), fx.Int32(0))
    count, before = packed_count & 0xFFFF, packed_count >> 16
    tiles = (count + BM - 1) // BM
    tstart = _prefix64(tiles, lane) - tiles
    if (fx.Int32(fx.block_idx.x) == 0) & (tid < E):
        _store(Counts, tid, count)
    for u in fx.range_constexpr(RPB):
        e = experts[u]
        safe = (e >= 0).select(e, fx.Int32(0))
        position = fx.Int32(gpu.shuffle_idx(before, safe, 64))
        for v in fx.range_constexpr(u):
            position = position + (experts[v] == e).select(fx.Int32(1), fx.Int32(0))
        r = start + u
        if tid == u:
            if r < R:
                _store(Local, r, e)
        if (tid == 0) & (e >= 0):
            _store(Routes, e * R + position, r)
        tile = fx.Int32(gpu.shuffle_idx(tstart, safe, 64)) + position // BM
        row = position % BM
        for h in fx.range_constexpr(HALVES):
            packed, exponent = _quantize_values(normalized[u][h])
            c8 = h * 256 + tid
            if e >= 0:
                dst = (tile * (D // 32) + c8 // 4) * BM + row
                _store(B, dst * 4 + c8 % 4, packed)
                if c8 % 4 == 0:
                    _store(BS, dst, exponent, fx.Uint8)


@flyc.kernel
def _reduce_masked(P: fx.Int64, Local: fx.Int64, Out: fx.Int64,
                   M: fx.Constexpr[int], D: fx.Constexpr[int], TOPK: fx.Constexpr[int],
                   ROWS: fx.Constexpr[int]):
    # Every output row is written; routes off this rank contribute nothing.
    tid = fx.Int32(fx.thread_idx.x)
    for rr in fx.range_constexpr(ROWS):
        token = fx.Int32(fx.block_idx.x) * ROWS + rr
        if token < M:
            local = [_load(Local, token * TOPK + k) for k in range(TOPK)]
            weights = [fx.Float32(1.0) for k in range(TOPK)]
            for c in fx.range_constexpr(D // 2048):
                n8 = c * 256 + tid
                values = [fx.Float32(0) for _ in range(8)]
                for k in fx.range_constexpr(TOPK):
                    projected = fx.Vector.filled(4, 0.0, fx.Float32).bitcast(fx.Int32)
                    if local[k] >= 0:
                        projected = _load4(P, (token * TOPK + k) * (D // 2) + n8 * 4)
                    halves = projected.bitcast(fx.BFloat16)
                    for j in fx.range_constexpr(8):
                        values[j] = values[j] + weights[k] * fx.Float32(halves[j])
                output = fx.Vector.from_elements([fx.BFloat16(v) for v in values])
                fx.ptr_store(output, fx.add_offset(_ptr(Out, fx.BFloat16, 16), token * D + n8 * 8))


def _split_store(red, values, wave, lane, WN, STRIDE=0):
    STRIDE = STRIDE or len(values)
    for v in fx.range_constexpr(len(values)):
        for j in fx.range_constexpr(4):
            fx.ptr_store(fx.Vector(values[v])[j], fx.add_offset(red, (((wave - WN) * STRIDE + v) * 4 + j) * 64 + lane))


def _split_reduce(red, values, wave, lane, WN, WK, STRIDE=0, PART=None):
    # Waves of one column group own consecutive K slices; the first keeps its
    # own slice in registers and adds the others, stored by _split_store.
    # With PART = (v0, v1) only those values are summed, after no barrier.
    STRIDE = STRIDE or len(values)
    v0, v1 = PART if PART else (0, len(values))
    if fx.const_expr(PART is None):
        gpu.barrier()
    sums = []
    for v in fx.range_constexpr(v0, v1):
        parts = []
        for j in fx.range_constexpr(4):
            total = fx.Float32(fx.Vector(values[v])[j])
            for k in fx.range_constexpr(1, WK):
                other = (k - 1) * WN + wave % WN
                total = total + fx.Float32(fx.ptr_load(fx.add_offset(red, ((other * STRIDE + v) * 4 + j) * 64 + lane)))
            parts.append(total)
        sums.append(parts)
    return sums


def _prefetch(fetch, KS, LOADS, RING):
    # Returns the operands of K step ks. With RING, step ks + LOADS is issued
    # before step ks is used; otherwise LOADS steps are issued as one batch.
    issued = []

    def get(ks):
        if fx.const_expr(RING):
            while len(issued) < min(ks + LOADS + 1, KS):
                issued.append(fetch(len(issued)))
        elif ks % LOADS == 0:
            issued.extend(fetch(k) for k in range(ks, min(ks + LOADS, KS)))
        return issued[ks]
    return get


@flyc.kernel
def _stage1_small(X: fx.Int64, A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64,
                  Routes: fx.Int64, Counts: fx.Int64, Q: fx.Int64, QS: fx.Int64,
                  R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int],
                  TOPK: fx.Constexpr[int], BM: fx.Constexpr[int], WN: fx.Constexpr[int],
                  WK: fx.Constexpr[int], E: fx.Constexpr[int], ADDR_BITS: fx.Constexpr[bool],
                  CACHE: fx.Constexpr[int], A_GLOBAL: fx.Constexpr[bool], LOADS: fx.Constexpr[int], RING: fx.Constexpr[bool], NC: fx.Constexpr[int],
                  TALL: fx.Constexpr[bool], TLOADS: fx.Constexpr[int], TLEAN: fx.Constexpr[bool], TSB: fx.Constexpr[bool], PMIN: fx.Constexpr[int]):
    # One workgroup per (row tile, 16 * WN * NC gate and up columns). It quantizes
    # its tile's rows into LDS once; its waves split K and sum in LDS.
    # TALL: a workgroup takes two tiles of one expert, so each weight load
    # feeds up to 2 * BM rows (fewer loads in flight for the taller bodies).
    # TLEAN: the tall body prefetches only weights. It reduces one tile at a time.
    THREADS = WN * WK * 64
    BN = WN * 16 * NC
    MR = BM // 16
    MRT = 2 * MR if TALL else MR
    KS = D // 128 // WK
    pid = fx.Int32(fx.block_idx.x)
    tile, nbase = pid // (I // BN), pid % (I // BN) * BN
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    smem = fx.SharedAllocator()
    if fx.const_expr(not A_GLOBAL):
        awords = fx.recast_iter(fx.Int32, smem.allocate(D // 2 * BM, alignment=16).peek().ptr)
        abytes = fx.recast_iter(fx.Uint8, smem.allocate(D // 32 * BM, alignment=16).peek().ptr)
        tokens = fx.recast_iter(fx.Int32, smem.allocate(BM * 4, alignment=16).peek().ptr)
    red = fx.recast_iter(fx.Float32, smem.allocate(max(WK - 1, 1) * WN * MRT * NC * 2 * 256 * 4, alignment=16).peek().ptr)
    hbuf = fx.recast_iter(fx.Float32, smem.allocate(MRT * 16 * (BN + 4) * 4, alignment=16).peek().ptr)
    total, expert, first_row, atile, span = _map_expert_pairs(Counts, tile, lane, E, BM, TALL, PMIN)
    if tile < total:
        live = _load(Counts, expert)
        if fx.const_expr(TALL):
            live = (live < first_row + span).select(live, first_row + span)
        if fx.const_expr(not A_GLOBAL):
            if tid < BM:
                rid = fx.Int32(0)
                if first_row + tid < live:
                    rid = _load(Routes, expert * R + first_row + tid)
                fx.ptr_store(rid // TOPK, fx.add_offset(tokens, tid))
            gpu.barrier()
            for j in fx.range_constexpr(BM * (D // 8) // THREADS):
                t = j * THREADS + tid
                row, c8 = t // (D // 8), t % (D // 8)
                token = fx.Int32(fx.ptr_load(fx.add_offset(tokens, row)))
                packed, exponent = _quantize_eight(X, token * (D // 8) + c8)
                index = (c8 // 4) * BM + row
                fx.ptr_store(packed, fx.add_offset(awords, index * 4 + c8 % 4))
                if c8 % 4 == 0:
                    fx.ptr_store(fx.Uint8(exponent), fx.add_offset(abytes, index))
            gpu.barrier()
        def body(MR):
            # MR row blocks of the tile are computed; the rest are padding.
            wn, wk = wave % WN, wave // WN
            ns = [nbase + (wn * NC + c) * 16 + lane % 16 for c in range(NC)]
            accum = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(MR * NC * 2)]
            lean = TLEAN and MR > BM // 16

            def load_acts(kg):
                acts = []
                for mi in fx.range_constexpr(MR):
                    if fx.const_expr(A_GLOBAL):
                        index = ((atile + mi // (BM // 16)) * (D // 32) + kg) * BM + mi % (BM // 16) * 16 + lane % 16
                        acts.append((_load4(A, index * 4), _load(AS, index, fx.Uint8)))
                    else:
                        index = kg * BM + mi * 16 + lane % 16
                        acts.append((fx.ptr_load(fx.add_offset(awords, index * 4), result_type=T.i32x4),
                                     fx.ptr_load(fx.add_offset(abytes, index))))
                return acts

            def fetch(ks):
                kg = (wk * KS + ks) * 4 + lane // 16
                acts = [] if lean else load_acts(kg)
                ws = []
                for c in fx.range_constexpr(NC):
                    ws.append(_load4(W, _weight_offset(expert, ns[c], kg, 2 * I, D, ADDR_BITS), CACHE))
                    ws.append(_load4(W, _weight_offset(expert, ns[c] + I, kg, 2 * I, D, ADDR_BITS), CACHE))
                # One scale word holds two adjacent 16-column groups.
                words = []
                for c in fx.range_constexpr(0, NC, 2):
                    words.append(_scale_word(WS, expert, ns[c], kg, 2 * I, D))
                    words.append(_scale_word(WS, expert, ns[c] + I, kg, 2 * I, D))
                return kg, acts, ws, words

            queue = _prefetch(fetch, KS, TLOADS, True) if MR > BM // 16 else _prefetch(fetch, KS, LOADS, RING)
            for ks in fx.range_constexpr(KS):
                kg, acts, ws, words = queue(ks)
                if fx.const_expr(lean):
                    acts = load_acts(kg)
                for c in fx.range_constexpr(NC):
                    sg = _scale_byte(words[c // 2 * 2], ns[c], kg)
                    su = _scale_byte(words[c // 2 * 2 + 1], ns[c] + I, kg)
                    for mi in fx.range_constexpr(MR):
                        av, asc = acts[mi]
                        v = (mi * NC + c) * 2
                        accum[v] = _mfma(av, ws[c * 2], accum[v], fx.Int32(asc), sg)
                        accum[v + 1] = _mfma(av, ws[c * 2 + 1], accum[v + 1], fx.Int32(asc), su)
                if fx.const_expr(TSB and MR > BM // 16):
                    # Keep later steps' loads out of this step (register budget).
                    rocdl.sched_barrier(0)
            if wk > 0:
                _split_store(red, accum, wave, lane, WN, MRT * NC * 2)
            tall = MR > BM // 16
            PASS = BM // 16 if tall else MR
            if fx.const_expr(tall):
                gpu.barrier()
            for p0 in fx.range_constexpr(0, MR, PASS):
                p1 = min(MR, p0 + PASS)
                if fx.const_expr(tall):
                    sums = [None] * (p0 * NC * 2) + _split_reduce(red, accum, wave, lane, WN, WK, MRT * NC * 2, (p0 * NC * 2, p1 * NC * 2))
                else:
                    sums = _split_reduce(red, accum, wave, lane, WN, WK, MRT * NC * 2)
                if wk == 0:
                    for v in fx.range_constexpr(p0 * NC, p1 * NC):
                        mi, c = v // NC, v % NC
                        for j in fx.range_constexpr(4):
                            x = _silu_bf16(sums[v * 2][j], sums[v * 2 + 1][j])
                            row = mi * 16 + lane // 16 * 4 + j
                            fx.ptr_store(x, fx.add_offset(hbuf, row * (BN + 4) + (wn * NC + c) * 16 + lane % 16))
            gpu.barrier()
            # Sixteen lanes quantize one row's 32-column group, two values each.
            for cp in fx.range_constexpr((MR * 16 * BN // 2 + THREADS - 1) // THREADS):
                t = cp * THREADS + tid
                if t < MR * 16 * BN // 2:
                    row, col = t // (BN // 2), t % (BN // 2) * 2
                    x0 = fx.Float32(fx.ptr_load(fx.add_offset(hbuf, row * (BN + 4) + col)))
                    x1 = fx.Float32(fx.ptr_load(fx.add_offset(hbuf, row * (BN + 4) + col + 1)))
                    a = _max(fx.absf(x0), fx.absf(x1))
                    a = _epilogue_reduce(a, True)
                    a = _max(a, fx.Float32(1.0e-10))
                    bits = a.bitcast(fx.Int32)
                    exponent = ((bits >> 23) & 255) - 2 + ((bits & 0x7fffff) > 0x400000).select(fx.Int32(1), fx.Int32(0))
                    scale = (exponent << 23).bitcast(fx.Float32)
                    q = fx.Int32(rocdl.cvt_scalef32_pk_fp4_f32(T.i32, fx.Int32(0), x0, x1, scale, 0))
                    dst = ((atile + row // BM) * (I // 32) + (nbase + col) // 32) * BM + row % BM
                    _store(Q, dst * 16 + col % 32 // 2, q, fx.Uint8)
                    if col % 32 == 0:
                        _store(QS, dst, exponent, fx.Uint8)

        def blocks(k):
            # The fewest 16-row blocks that hold the tile's live rows.
            if fx.const_expr(k == 1):
                body(1)
            else:
                if live - first_row > (k - 1) * 16:
                    body(k)
                else:
                    blocks(k - 1)
        blocks(MRT)


@flyc.kernel
def _stage2_small(A: fx.Int64, AS: fx.Int64, W: fx.Int64, WS: fx.Int64, Routes: fx.Int64,
                  Counts: fx.Int64, P: fx.Int64, Local: fx.Int64,
                  R: fx.Constexpr[int], D: fx.Constexpr[int], I: fx.Constexpr[int], TOPK: fx.Constexpr[int], OUT: fx.Constexpr[bool],
                  BM: fx.Constexpr[int], WN: fx.Constexpr[int], WK: fx.Constexpr[int],
                  E: fx.Constexpr[int], ADDR_BITS: fx.Constexpr[bool], CACHE: fx.Constexpr[int],
                  LOADS: fx.Constexpr[int], RING: fx.Constexpr[bool], NC: fx.Constexpr[int],
                  TALL: fx.Constexpr[bool], TLOADS: fx.Constexpr[int], TLEAN: fx.Constexpr[bool], TSB: fx.Constexpr[bool], PMIN: fx.Constexpr[int]):
    # One workgroup per (row tile, 16 * WN * NC output columns); waves split K.
    # TLEAN: the tall body prefetches only weights. It handles one tile's rows
    # per epilogue pass, so its epilogue needs no more registers than one tile's.
    # TALL pairs an expert's tiles as in _stage1_small.
    # Each wave owns NC adjacent 16-column groups that share its A operands.
    BN = WN * 16 * NC
    MR = BM // 16
    MRT = 2 * MR if TALL else MR
    KS = I // 128 // WK
    pid = fx.Int32(fx.block_idx.x)
    tile, nbase = pid // (D // BN), pid % (D // BN) * BN
    tid = fx.Int32(fx.thread_idx.x)
    lane, wave = tid % 64, tid // 64
    red = fx.recast_iter(fx.Float32, fx.SharedAllocator().allocate(max(WK - 1, 1) * WN * MRT * NC * 256 * 4, alignment=16).peek().ptr)
    total, expert, first_row, atile, span = _map_expert_pairs(Counts, tile, lane, E, BM, TALL, PMIN)
    if tile < total:
        count = _load(Counts, expert)
        if fx.const_expr(TALL):
            count = (count < first_row + span).select(count, first_row + span)
        def body(MR):
            # MR row blocks of the tile are computed; the rest are padding.
            wn, wk = wave % WN, wave // WN
            ns = [nbase + (wn * NC + c) * 16 + lane % 16 for c in range(NC)]
            accum = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range(MR * NC)]
            lean = TLEAN and MR > BM // 16

            def load_acts(kg):
                acts = []
                for mi in fx.range_constexpr(MR):
                    index = ((atile + mi // (BM // 16)) * (I // 32) + kg) * BM + mi % (BM // 16) * 16 + lane % 16
                    acts.append((_load4(A, index * 4), _load(AS, index, fx.Uint8)))
                return acts

            def fetch(ks):
                kg = (wk * KS + ks) * 4 + lane // 16
                acts = [] if lean else load_acts(kg)
                # One scale word holds two adjacent 16-column groups.
                words = [_scale_word(WS, expert, ns[c], kg, D, I) for c in range(0, NC, 2)]
                return (kg, acts, [_load4(W, _weight_offset(expert, ns[c], kg, D, I, ADDR_BITS), CACHE) for c in range(NC)], words)

            queue = _prefetch(fetch, KS, TLOADS, True) if MR > BM // 16 else _prefetch(fetch, KS, LOADS, RING)
            for ks in fx.range_constexpr(KS):
                kg, acts, ws, words = queue(ks)
                if fx.const_expr(lean):
                    acts = load_acts(kg)
                for c in fx.range_constexpr(NC):
                    s = _scale_byte(words[c // 2], ns[c], kg)
                    for mi in fx.range_constexpr(MR):
                        av, asc = acts[mi]
                        accum[mi * NC + c] = _mfma(av, ws[c], accum[mi * NC + c], fx.Int32(asc), s)
                if fx.const_expr(TSB and MR > BM // 16):
                    # Keep later steps' loads out of this step (register budget).
                    rocdl.sched_barrier(0)
            if wk > 0:
                _split_store(red, accum, wave, lane, WN, MRT * NC)
            if fx.const_expr(MR > BM // 16):
                # One tile's rows at a time: reduce, then store them.
                gpu.barrier()
                if wk == 0:
                    for p0 in fx.range_constexpr(0, MR, BM // 16):
                        p1 = min(MR, p0 + BM // 16)
                        part = _split_reduce(red, accum, wave, lane, WN, WK, MRT * NC, (p0 * NC, p1 * NC))
                        epilogue([None] * (p0 * NC) + part, ns, p0, p1)
            else:
                sums = _split_reduce(red, accum, wave, lane, WN, WK, MRT * NC)
                if wk == 0:
                    epilogue(sums, ns, 0, MR)

        def epilogue(sums, ns, m0, m1):
            targets = {}
            if fx.const_expr(OUT):
                # All row lookups of the pass are issued before its first conditional store.
                for mi in fx.range_constexpr(m0, m1):
                    for j in fx.range_constexpr(4):
                        row = first_row + mi * 16 + lane // 16 * 4 + j
                        valid = row < count
                        rid = valid.select(_load(Routes, valid.select(expert * R + row, fx.Int32(0))), fx.Int32(0))
                        targets[mi * 4 + j] = (valid, rid)
                targets = {k: (valid, rid // TOPK, fx.Float32(1.0), _local_routes(Local, rid // TOPK, TOPK)) for k, (valid, rid) in targets.items()}
            for v in fx.range_constexpr(m0 * NC, m1 * NC):
                mi, c = v // NC, v % NC
                n = ns[c]
                for j in fx.range_constexpr(4):
                    if fx.const_expr(OUT):
                        # Lane pairs hold adjacent columns; even lanes emit both.
                        valid, token, weight, n_local = targets[mi * 4 + j]
                        value = valid.select(weight * sums[mi * NC + c][j], fx.Float32(0))
                        high = fx.Float32(gpu.shuffle_xor(value, 1, 64))
                        if valid & (lane % 2 == 0):
                            if n_local == 1:
                                _store(P, (token * D + n) // 2, fx.Vector.from_elements([fx.BFloat16(value), fx.BFloat16(high)]).bitcast(fx.Int32)[0])
                            if n_local != 1:
                                _atomic_add_bf16x2(P, (token * D + n) // 2, value, high)
                    else:
                        row = first_row + mi * 16 + lane // 16 * 4 + j
                        if row < count:
                            route = _load(Routes, expert * R + row)
                            _store(P, route * D + n, sums[mi * NC + c][j], fx.BFloat16)

        def blocks(k):
            if fx.const_expr(k == 1):
                body(1)
            else:
                if count - first_row > (k - 1) * 16:
                    body(k)
                else:
                    blocks(k - 1)
        blocks(MRT)


def _config(M):
    """Tile and pipeline choices per token count."""
    c = dict(BM=16, BN1=64, WAVES1=4, PF1=False, KSTEP1=1, QMAX=False, QSHUFFLE=False,
             EPILOGUE_DPP=True, GROUP_M=1, ADDR_BITS=False, CACHE1=0, CACHE2=0,
             BN2=64, PF2=False, KSTEP2=1, MFMA32=False, ROW_MAJOR1=False, ROW_MAJOR2=False,
             GATHER_BLOCKS=1024, GATHER_UNROLL=2, REDUCE_ROWS=1,
             SMALL=M <= 4096, A_GLOBAL=True, OUT=True, SPLIT2=1, PINGPONG1=False, DMA1=False, APF1=False, APF2=True, ZERO1=False, LOADS1=2, LOADS2=1, RING1=False, RING2=False, FUSE=True, NC1=1, NC2=1, ROUTE_ONE=4096, WN1=4, WK1=4, WN2=2, WK2=4, RG=0, TALL1=False, TALL2=False, TLOADS1=1, TLOADS2=1, TLEAN1=True, TLEAN2=True, TSB1=True, TSB2=True, PMIN1=2, PMIN2=2)
    if M <= 4096:
        c.update(CACHE1=2, CACHE2=2, BM=16, WN2=4, WK2=2, RING2=True, ROUTE_ONE=8192, RG=8,
                 TALL1=True, TALL2=True, TLEAN1=False, TLOADS1=0)
        if M >= 512:
            c.update(WN2=2, NC2=2)
        if M >= 1344:
            c.update(BM=32, WK1=1, LOADS1=2, RING1=True, TLOADS1=2)
    else:
        c.update(BM=128, BN1=128, PF1=True, KSTEP1=2, QSHUFFLE=True,
                 GROUP_M=4, BN2=128, KSTEP2=2, ROW_MAJOR2=True, SPLIT2=2, ZERO1=M >= 16384)
    return c


@functools.cache
def _build(M, D, I, E, G, REP, EPS, GAIN):
    K = 2
    R = M * K
    c = _config(M)
    BM, BN1, BN2, WAVES1 = c['BM'], c['BN1'], c['BN2'], c['WAVES1']
    MULTI = R > c['ROUTE_ONE']
    CHUNKS = 4 if MULTI else (R + 1023) // 1024
    route_grid = (R + CHUNKS * 1024 - 1) // (CHUNKS * 1024)
    first = min(E, R)
    max_tiles = first + (R - first) // BM
    GATHER_BLOCKS = min(c['GATHER_BLOCKS'], max_tiles * BM)
    REDUCE_ROWS = c['REDUCE_ROWS']
    SMALL = c['SMALL']
    FUSED = SMALL and c['A_GLOBAL'] and c['FUSE'] and R <= 256 and E <= 64
    OUT = c['OUT']
    RG = c['RG'] if SMALL and c['A_GLOBAL'] and not FUSED and not MULTI else 0
    sizes = [E * 4, E * R * 4, R * 4, max_tiles * 4, max_tiles * 4, 4,
             max_tiles * BM * D // 2, max_tiles * BM * D // 32,
             max_tiles * BM * I // 2, max_tiles * BM * I // 32, 0 if OUT else R * D * 2]
    offsets, total_bytes = [], 0
    for size in sizes:
        offsets.append(total_bytes)
        total_bytes += (size + 255) // 256 * 256

    @flyc.jit
    def launch_all(X: fx.Int64, W1: fx.Int64, W2: fx.Int64, Wn: fx.Int64,
                   Ids: fx.Int64, S1: fx.Int64, S2: fx.Int64, Mask: fx.Int64, Out: fx.Int64,
                   Counts: fx.Int64, Routes: fx.Int64, Local: fx.Int64, TE: fx.Int64, TR: fx.Int64,
                   Total: fx.Int64, AQ: fx.Int64, AS: fx.Int64, HQ: fx.Int64, HS: fx.Int64, P: fx.Int64,
                   Enabled: fx.Int32, stream: fx.Stream):
        """Route, gather-quantize, both projections and the masked reduction."""
        # flyc.compile also calls the compiled host wrapper once. Its dry call
        # has no input tensors yet; every real invocation sets Enabled to one.
        Target = Out if OUT else P
        if Enabled != 0:
            if fx.const_expr(MULTI):
                _clear(Counts, E).launch(grid=(1,), block=(64,), stream=stream)
            if fx.const_expr(not FUSED and not RG):
                _route_masked(Ids, Mask, Counts, Routes, Local, R, E, G, CHUNKS, MULTI).launch(grid=(route_grid,), block=(1024,), stream=stream)
            if fx.const_expr(SMALL):
                if fx.const_expr(RG):
                    _route_gather(X, AQ, AS, Ids, Mask, Counts, Routes, Local, Out, M, OUT, R, D, K, BM, E, G, RG, Wn, REP, EPS, GAIN).launch(grid=((R + RG - 1) // RG,), block=(256,), stream=stream)
                elif fx.const_expr(c['A_GLOBAL']):
                    _gather_input(X, AQ, AS, Routes, Counts, TE, TR, Total, Local, Out, M, OUT, R, D, K, BM, E, GATHER_BLOCKS, c['GATHER_UNROLL'], 0, Ids, Mask, G, FUSED, Wn, REP, EPS, GAIN).launch(grid=(GATHER_BLOCKS,), block=(256,), stream=stream)
                _stage1_small(X, AQ, AS, W1, S1, Routes, Counts, HQ, HS, R, D, I, K, BM, c['WN1'], c['WK1'], E, c['ADDR_BITS'], c['CACHE1'], c['A_GLOBAL'], c['LOADS1'], c['RING1'], c['NC1'], c['TALL1'], c['TLOADS1'], c['TLEAN1'], c['TSB1'], c['PMIN1']).launch(grid=(max_tiles * (I // (16 * c['WN1'] * c['NC1'])),), block=(c['WN1'] * c['WK1'] * 64,), stream=stream)
                _stage2_small(HQ, HS, W2, S2, Routes, Counts, Target, Local, R, D, I, K, OUT, BM, c['WN2'], c['WK2'], E, c['ADDR_BITS'], c['CACHE2'], c['LOADS2'], c['RING2'], c['NC2'], c['TALL2'], c['TLOADS2'], c['TLEAN2'], c['TSB2'], c['PMIN2']).launch(grid=(max_tiles * (D // (16 * c['WN2'] * c['NC2'])),), block=(c['WN2'] * c['WK2'] * 64,), stream=stream)
            else:
                _gather_input(X, AQ, AS, Routes, Counts, TE, TR, Total, Local, Out, M, OUT, R, D, K, BM, E, GATHER_BLOCKS, c['GATHER_UNROLL'], I // BN1 if c['ZERO1'] else 0, Ids, Mask, G, False, Wn, REP, EPS, GAIN).launch(grid=(GATHER_BLOCKS,), block=(256,), stream=stream)
                _gemm1(AQ, AS, W1, S1, Routes, Counts, TE, TR, Total, HQ, HQ, HS, R, D, I, K, BM, BN1, True, 1, True,
                       c['PF1'], True, c['QMAX'], False, c['KSTEP1'], WAVES1, c['ADDR_BITS'], c['GROUP_M'], c['PINGPONG1'], c['DMA1'], 0,
                       c['CACHE1'], True, c['ROW_MAJOR1'], c['QSHUFFLE'], c['EPILOGUE_DPP'], c['APF1'], Local, Out, M, OUT and c['ZERO1']).launch(grid=(max_tiles * (I // BN1), 1), block=(WAVES1 * 64,), stream=stream)
                _gemm2(HQ, HS, W2, S2, Routes, Counts, TE, TR, Total, Target, Local, R, D, I, K, OUT, BM // c['SPLIT2'], BN2, True, True, c['PF2'], True, False, False,
                       c['KSTEP2'], c['MFMA32'], True, c['GROUP_M'], True, 0, c['CACHE2'], True, c['ROW_MAJOR2'], c['SPLIT2'], c['APF2']).launch(grid=(max_tiles * c['SPLIT2'] * (D // BN2),), block=(256,), stream=stream)
            if fx.const_expr(not OUT):
                _reduce_masked(P, Local, Out, M, D, K, REDUCE_ROWS).launch(grid=((M + REDUCE_ROWS - 1) // REDUCE_ROWS,), block=(256,), stream=stream)

    compiled = flyc.compile(launch_all, *([0] * 20), 0, fx.Stream(None))
    return compiled, offsets, total_bytes


def run(*, hidden_states, norm_weight, topk_ids, expert_mask, w1, w1_scale, w2, w2_scale,
        eps, gain_center, out_dtype, out):
    """Each route's unweighted expert output over this rank's experts, written into ``out``."""
    T, D = int(hidden_states.shape[0]), int(hidden_states.shape[1])
    REP = int(topk_ids.shape[1])
    E, I = int(w1.shape[0]), int(w1.shape[1]) // 2
    G = int(expert_mask.shape[0])
    bits = lambda value: int(np.float32(value).view(np.int32))
    compiled, offsets, total_bytes = _build(T * REP, D, I, E, G, REP, bits(eps), bits(gain_center))
    scratch = torch.empty(total_bytes, dtype=torch.uint8, device=hidden_states.device)
    base = scratch.data_ptr()
    inputs = [x.data_ptr() for x in (hidden_states, w1, w2, norm_weight, topk_ids, w1_scale, w2_scale, expert_mask, out)]
    compiled(*inputs, *[base + o for o in offsets], 1, fx.Stream(torch.cuda.current_stream()))
